local function fill(layer, frame, data)
  local img = Image(64, 64, ColorMode.INDEXED)
  img:clear(0)
  for i = 1, #data // 2 do
    local v = tonumber(data:sub(2 * i - 1, 2 * i), 16)
    if v > 0 then img:putPixel((i - 1) % 64, (i - 1) // 64, v) end
  end
  spr:newCel(layer, frame, img, Point(0, 0))
end
